{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "size",
      "type": "'static' | 'fill'",
      "description": "Flex grow behavior: static keeps natural size, fill expands to consume remaining space.",
      "default": "'static'"
    },
    {
      "name": "isScrollable",
      "type": "boolean",
      "description": "Enables scrollable overflow (overflow: auto). StackItem already applies the flex min-height/min-width reset, so <StackItem size=\"fill\" isScrollable> is a complete scroll region. Matches isScrollable on LayoutContent and LayoutPanel. While its content overflows, a div or span item is a group named by aria-label, or by a translated \"Content\"; another element keeps its own role.",
      "default": "false"
    },
    {
      "name": "crossAlignSelf",
      "type": "'start' | 'center' | 'end' | 'stretch'",
      "description": "Override the cross-axis alignment for this individual item, ignoring the parent stack alignment."
    },
    {
      "name": "as",
      "type": "ElementType",
      "description": "HTML element to render as the item wrapper.",
      "default": "'div'"
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "Item content."
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
    },
    {
      "name": "className",
      "type": "string",
      "description": "Class name added to the item element, after the component styles."
    },
    {
      "name": "style",
      "type": "CSSProperties",
      "description": "Inline styles for the item element."
    },
    {
      "name": "ref",
      "type": "Ref<HTMLElement>",
      "description": "Ref to the rendered item element."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
